/**
 * Return one page of what can be added with createApp: the apps in OpenBot's own catalogue (source catalogue) in the catalogue's own order, then apps from the wider directory (source directory), the ones a person signs in to before the ones that take a key, each by title, ignoring case, and then by id. So a screen can show the pages as they arrive, in the order it shows them. appId names the app an entry was added as, or is null. An app that connects with a key but signs in through its vendor is listed once, as the sign-in, with keyVersion naming the same app connected with its key. search narrows the list to entries whose name or description holds it, ignoring case. source narrows it to one kind. Anybody signed in may read it, the wider directory included. While the organization's apps are open (getAppsSetting), anybody may add what they find (createApp); where they're locked down an administrator adds it, and anybody else asks for it (createAppAccessRequest). Where no directory is set up, the list holds the catalogue only and source=directory is unavailable. In the personal edition the catalogue leaves out entries meant for a team, unless they're already added. A missing cursor starts at the first page and nextCursor null ends the list. A cursor belongs to the search and source that made it, so changing either starts again without one.
 * @summary List the apps that can be added
 */

export const ListAppDirectoryParams = zod.object({
  organizationId: zod
    .string()
    .min(1)
    .describe(
      "The organization, by its id or its slug. One the caller is not a member of answers as one that does not exist, `default` included.",
    ),
});

export const listAppDirectoryQuerySearchMax = 200;

export const listAppDirectoryQuerySearchRegExp = new RegExp("^[^\\x00]*$");
export const listAppDirectoryQueryLimitDefault = 50;
export const listAppDirectoryQueryLimitMax = 100;

export const listAppDirectoryQueryCursorMax = 4096;

export const listAppDirectoryQueryCursorRegExp = new RegExp("^[A-Za-z0-9_-]+$");

export const ListAppDirectoryQueryParams = zod.object({
  search: zod
    .string()
    .max(listAppDirectoryQuerySearchMax)
    .regex(listAppDirectoryQuerySearchRegExp)
    .optional()
    .describe(
      "Part of an entry's name or description, matched without regard to case.",
    ),
  source: zod
    .enum(["catalogue", "directory"])
    .optional()
    .describe("Only the catalogue, or only the wider directory."),
  limit: zod
    .int()
    .min(1)
    .max(listAppDirectoryQueryLimitMax)
    .default(listAppDirectoryQueryLimitDefault)
    .describe("Most items in one page."),
  cursor: zod
    .string()
    .min(1)
    .max(listAppDirectoryQueryCursorMax)
    .regex(listAppDirectoryQueryCursorRegExp)
    .optional()
    .describe(
      "Opaque continuation from the previous page's nextCursor, bound to the organization and the filters that made it. The server only ever issues cursors written in URL-safe base64 (letters, digits, - and _, no padding) and refuses anything else, so the pattern says so. A cursor that fits the pattern can still be refused: one this list never gave out, or one made for another organization or other filters.",
    ),
});

export const listAppDirectoryResponseEntriesItemTwoActionCountMin = 0;

export const listAppDirectoryResponseEntriesItemTwoClassifiedCountMin = 0;

export const listAppDirectoryResponseEntriesItemTwoPermissionCountMin = 0;

export const listAppDirectoryResponseEntriesItemTwoScopedActionCountMin = 0;

export const listAppDirectoryResponseEntriesItemTwoKeyVersionActionCountMin = 0;

export const listAppDirectoryResponseNextCursorMax = 4096;

export const listAppDirectoryResponseNextCursorRegExp = new RegExp(
  "^[A-Za-z0-9_-]+$",
);
export const listAppDirectoryResponseTotalMin = 0;

export const ListAppDirectoryResponse = zod.object({
  entries: zod
    .array(
      zod
        .union([
          zod
            .object({
              id: zod.string().describe("The entry's id, for createApp."),
              source: zod.enum(["catalogue"]),
              title: zod.string(),
              summary: zod.string().describe("What the app is for."),
              appId: zod
                .string()
                .nullable()
                .describe("The app it was added as, or null."),
              vendor: zod.string().describe("Who makes the app."),
              docsUrl: zod.string().describe("The vendor's documentation."),
              auth: zod
                .enum(["none", "deployment-bearer", "user-oauth", "builtin"])
                .describe(
                  "How the app is reached: needing nothing, with a key an administrator gives for everybody, as each person through their own sign-in, or inside OpenBot itself.",
                ),
              perInstance: zod
                .boolean()
                .describe(
                  "Whether the vendor gives every customer their own host (instanceHost).",
                ),
              oneStep: zod
                .boolean()
                .describe(
                  "Whether connecting needs nothing typed first: no account at all, or a vendor OpenBot registers itself with.",
                ),
            })
            .describe("An app in OpenBot's own catalogue."),
          zod
            .object({
              id: zod.string().describe("The entry's id, for createApp."),
              source: zod.enum(["directory"]),
              title: zod.string(),
              summary: zod
                .string()
                .describe("What the directory says the app does."),
              appId: zod
                .string()
                .nullable()
                .describe("The app it was added as, or null."),
              logo: zod
                .string()
                .nullable()
                .describe("The address of the app's logo, where it has one."),
              categories: zod.array(zod.string()),
              actionCount: zod
                .int()
                .min(listAppDirectoryResponseEntriesItemTwoActionCountMin)
                .describe(
                  "How many actions the app offers. Adding it offers every one of them to Bots.",
                ),
              classifiedCount: zod
                .int()
                .min(listAppDirectoryResponseEntriesItemTwoClassifiedCountMin)
                .nullable()
                .describe(
                  "How many of those actions say whether they only read. 0 means none do, so each is asked about like a change. Null means the directory doesn't say.",
                ),
              permissionCount: zod
                .int()
                .min(listAppDirectoryResponseEntriesItemTwoPermissionCountMin)
                .nullable()
                .describe(
                  "How many separate permissions the actions ask a person for. Null means the directory doesn't say.",
                ),
              scopedActionCount: zod
                .int()
                .min(listAppDirectoryResponseEntriesItemTwoScopedActionCountMin)
                .nullable()
                .describe(
                  "How many actions ask for a permission at all. The rest work with any connection. Null means the directory doesn't say.",
                ),
              connectsWith: zod
                .enum(["sign-in", "key", "nothing"])
                .describe("How a person connects the app once it is added."),
              keyVersion: zod
                .object({
                  appId: zod
                    .string()
                    .nullable()
                    .describe("The app the key version was added as, or null."),
                  title: zod
                    .string()
                    .describe(
                      "What the key version is called once added, so it reads apart from the sign-in beside it: the app's own name followed by (key), as in PostHog (key).",
                    ),
                  actionCount: zod
                    .int()
                    .min(
                      listAppDirectoryResponseEntriesItemTwoKeyVersionActionCountMin,
                    )
                    .describe("How many actions the key version offers."),
                })
                .optional()
                .describe(
                  "The same app connected with a key, for an app the directory offers as a sign-in in place of its key. Add it with createApp and connectsWith key. Absent for any other app.",
                ),
            })
            .describe("An app from the wider app directory."),
        ])
        .describe("One app that can be added, by where it comes from."),
    )
    .describe(
      "The catalogue in its own order, then the wider directory: apps a person signs in to before apps that take a key (connectsWith key), each by title, ignoring case, and then by id.",
    ),
  nextCursor: zod
    .string()
    .max(listAppDirectoryResponseNextCursorMax)
    .regex(listAppDirectoryResponseNextCursorRegExp)
    .nullable()
    .describe(
      "Pass as cursor for the next page. Null ends the list. Written in URL-safe base64, the only form the cursor parameter accepts.",
    ),
  total: zod
    .int()
    .min(listAppDirectoryResponseTotalMin)
    .optional()
    .describe(
      "How many entries the whole list holds for this search and source, across every page, so a screen can say how many there are while it reads only the first page.",
    ),
});

